const CLIENT="(()=>{\n'use strict';const config=JSON.parse(document.getElementById('page-config').textContent),l=config.lang,t=config.sourceLabels,U=config.labels;\nconst $=s=>document.querySelector(s);document.addEventListener('click',e=>{const menu=$('#language-menu');if(menu&&!menu.contains(e.target))menu.open=false});document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#language-menu').open=false});\nconst photoButtons=[...document.querySelectorAll('[data-image]')];function selectPhoto(button){const main=$('#mainphoto');if(main){main.src=button.dataset.image;const counter=$('#photo-counter');if(counter)counter.textContent=(Number(button.dataset.photoIndex||0)+1)+' / '+document.querySelectorAll('[data-photo-index]').length;photoButtons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.image===button.dataset.image)))} }\nphotoButtons.forEach(b=>b.onclick=()=>selectPhoto(b));const wanted=Number(new URL(location.href).searchParams.get('photo'));if(wanted>0){let b=document.querySelector('[data-photo-index=\"'+wanted+'\"]');if(b)selectPhoto(b)}\nfor(const panel of document.querySelectorAll('.option-scroll')){let startY=0,startTop=0,dragged=false,active=false;panel.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0)return;startY=e.clientY;startTop=panel.scrollTop;dragged=false;active=true});panel.addEventListener('pointermove',e=>{if(!active)return;let d=e.clientY-startY;if(Math.abs(d)>5){dragged=true;panel.classList.add('dragging');panel.scrollTop=startTop-d;e.preventDefault()}});window.addEventListener('pointerup',()=>{active=false;panel.classList.remove('dragging')});panel.addEventListener('click',e=>{if(dragged){e.preventDefault();e.stopImmediatePropagation();dragged=false}},true)}\nlet cp=$('#copy');if(cp)cp.onclick=async()=>{try{await navigator.clipboard.writeText(cp.dataset.url);cp.textContent=t[22]}catch{cp.textContent=U.copyFailed;let el=document.createElement('input');el.className='copy-fallback';el.value=cp.dataset.url;el.readOnly=true;cp.after(el);el.select()}};\nlet fxPromise;async function getRates(){if(!fxPromise)fxPromise=fetch('/api/rates').then(async r=>{if(!r.ok)throw Error();let d=await r.json();if(!d.rates)throw Error();return d}).catch(e=>{fxPromise=null;throw e});return fxPromise}\nconst currency=$('#currency');let choice='USD';try{choice=localStorage.getItem('litbuy-currency')||'USD'}catch{}if(![...currency.options].some(o=>o.value===choice))choice='USD';currency.value=choice;\nasync function applyCurrency(){let target=currency.value;try{const data=target==='USD'?{rates:{USD:1},date:null}:await getRates();if(!data.rates[target])throw Error();document.querySelectorAll('[data-usd]').forEach(el=>{let v=Number(el.dataset.usd);el.textContent=new Intl.NumberFormat(l==='zh'?'zh-CN':l,{style:'currency',currency:target}).format(v*data.rates[target])+' '+target});document.querySelectorAll('.fx-status').forEach(e=>e.textContent=data.date?U.fx+' · Frankfurter · '+data.date:'');try{localStorage.setItem('litbuy-currency',target)}catch{}}catch{currency.value='USD';document.querySelectorAll('[data-usd]').forEach(el=>el.textContent='$'+Number(el.dataset.usd).toFixed(2)+' USD');document.querySelectorAll('.fx-status').forEach(e=>e.textContent=U.fxError)}}\ncurrency.onchange=applyCurrency;applyCurrency();\nconst allPhotos=[...document.querySelectorAll('[data-photo-index]')];\nfor(const b of document.querySelectorAll('[data-photo-step]'))b.onclick=()=>{const variants=[...document.querySelectorAll('[data-style-image]')];const selected=variants.findIndex(v=>v.getAttribute('aria-pressed')==='true');if(selected>=0){variants[(selected+Number(b.dataset.photoStep)+variants.length)%variants.length].click();return;}let i=allPhotos.findIndex(p=>p.getAttribute('aria-pressed')==='true');i=(i+Number(b.dataset.photoStep)+allPhotos.length)%allPhotos.length;if(allPhotos[i])selectPhoto(allPhotos[i]);};\nconst zoom=$('#photo-zoom'),dialog=$('#photo-dialog');if(zoom&&dialog){zoom.onclick=()=>{dialog.querySelector('img').src=$('#mainphoto').src;dialog.showModal();};dialog.querySelector('button').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close()};}\nconst input=$('#image-file');if(!input)return;$('#choose-image').onclick=()=>input.click();\nconst status=$('#image-status'),coverage=$('#coverage'),results=$('#image-results'),heading=$('#results-heading');let dbPromise,serial=0;\nfunction getIndex(){if(!dbPromise)dbPromise=fetch('/api/image-index?lang='+l).then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{coverage.textContent=U.coverage+': '+data.products+' / '+data.total+' · '+U.images+': '+data.images+' · '+U.unavailable+': '+data.missingImages+' · '+U.updated+': '+new Date(data.updated).toLocaleString(l==='zh'?'zh-CN':l);return data}).catch(e=>{dbPromise=null;throw e});return dbPromise}\ngetIndex().catch(()=>status.textContent=t[34]);\nfunction vector(img){let c=document.createElement('canvas');c.width=8;c.height=8;let cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(img,0,0,8,8);let a=cx.getImageData(0,0,8,8).data,sig=[];for(let i=0;i<a.length;i+=4){sig.push(a[i]>>3,a[i+1]>>3,a[i+2]>>3)}c.width=9;c.height=8;cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(img,0,0,9,8);a=cx.getImageData(0,0,9,8).data;let bits='';const lum=i=>.299*a[i]+.587*a[i+1]+.114*a[i+2];for(let y=0;y<8;y++)for(let x=0;x<8;x++){let i=(y*9+x)*4;bits+=lum(i+4)>lum(i)?'1':'0'}return {sig,bits}}\nconst bitcount=[0,1,1,2,1,2,2,3,1,2,2,3,2,3,3,4];function distance(q,entry){let s=entry[2],c=0;for(let i=0;i<192;i++){let d=q.sig[i]-s.charCodeAt(i);c+=d*d}let h=0;for(let i=0;i<16;i++)h+=bitcount[parseInt(q.bits.slice(i*4,i*4+4),2)^parseInt(entry[1][i],16)];return Math.sqrt(c/192)/31*.7+(h/64)*.3}\ninput.onchange=async()=>{const run=++serial;const file=input.files[0];if(!file)return;$('#file-name').textContent=file.name;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024){status.textContent=U.failed;return}results.replaceChildren();heading.hidden=true;status.textContent=U.searching;if(window.lastUploadURL)URL.revokeObjectURL(window.lastUploadURL);let blob=URL.createObjectURL(file);window.lastUploadURL=blob;try{let img=new Image();img.src=blob;await img.decode();const preview=$('#query-image');preview.src=blob;preview.hidden=false;let q=vector(img),data=await getIndex();if(run!==serial)return;if(!data.images){status.textContent=U.empty;return}let found=[];for(let i=0;i<data.items.length;i++){let p=data.items[i],best=null;for(let j=0;j<p[2].length;j++){let e=p[2][j];let raw=atob(e[2]);let d=distance(q,[e[0],e[1],raw]);if(!best||d<best.score)best={score:d,entry:e,ix:j}}if(best)found.push({p,...best});if(i%160===0)await new Promise(resolve=>setTimeout(resolve,0));if(run!==serial)return}found.sort((a,b)=>a.score-b.score);const bestScore=found[0]?.score??1;found=found.filter(f=>f.score<=Math.min(.24,bestScore+.075));heading.hidden=found.length===0;status.textContent=found.length?U.matches+' · '+Math.min(20,found.length):t[27];\nfor(const f of found.slice(0,20)){const article=document.createElement('article');article.className='card';const a=document.createElement('a');a.className='photo';a.href='/'+l+'/product'+f.p[0]+'?photo='+f.entry[3];const im=document.createElement('img');im.src=f.entry[0];im.alt=U.photo;im.loading='lazy';a.append(im);const title=document.createElement('h3'),link=document.createElement('a');link.href=a.href;link.textContent=f.p[3]?.[l]||f.p[1];title.append(link);const note=document.createElement('p');note.className='result-info';note.textContent=U.photo+' '+(Number(f.entry[3])+1);article.append(a,title,note);results.append(article)}\n}catch(e){status.textContent=U.failed;URL.revokeObjectURL(blob)}};\n})();\n";



