const extraCSS=`body{background:#fff;color:#202024}.brand{display:flex;align-items:center;gap:10px;letter-spacing:0}.brand img{width:120px;height:auto}.subbrand{font-size:9px;letter-spacing:1.5px;border-left:1px solid #d8d8dc;padding-left:9px;color:#777}.nav{gap:22px}.nav nav{margin-left:12px;gap:20px;white-space:nowrap}.nav .tools{gap:8px}.join,.btn,.search button{background:#ff962e;border-color:#ff962e;color:#151515}.secondary{background:white;border-color:#d8d8df}.heroart{background:#fff3e6}.heroart:before,.heroart:after{border-color:#f1d7b8}.eyebrow{color:#9a5521}.eyebrow:before{background:#ff962e}.chip.active,.chip:hover{background:#222;color:#fff;border-color:#222}.camera{display:flex;align-items:center;justify-content:center;padding:0 14px;color:#686775}.detail{grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);max-width:1120px;margin:30px auto 40px;gap:48px}.mainphoto{background:#f6f6f6}.detail h1{font-size:31px;line-height:1.2}.bigprice{font-size:31px;font-weight:bold}.actions{display:grid;grid-template-columns:1fr 1fr;gap:10px}.actions>.btn:first-child{grid-column:1/-1}.actions .btn{padding:14px 10px}.actions>.agents{grid-column:1/-1;margin:0}.actions .agents summary{padding:14px}.actions .btn.secondary{font-size:12px}.agents{margin:12px 0;border:1px solid #d8d8df;border-radius:6px}.agents summary{padding:14px;cursor:pointer;font-size:13px;font-weight:bold}.agent-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding:12px;max-height:260px;overflow:auto}.agent-grid a{padding:12px 8px;border:1px solid #eee;border-radius:5px;font-size:12px;text-align:center}.agent-grid a:hover{background:#fff3e6}.gallery-panel{margin-top:24px;border-top:1px solid #eee;padding-top:18px}.gallery-panel h2,.qc-section h2{font-size:20px;margin:5px 0 15px}.option-scroll{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px;max-height:230px;overflow:auto;overscroll-behavior:contain;padding:4px 8px 4px 0;scrollbar-gutter:stable;cursor:grab}.option-scroll button{padding:0;border:2px solid transparent;border-radius:7px;overflow:hidden;background:#f3f3f3;aspect-ratio:1;min-width:0}.option-scroll button[aria-pressed=true]{border-color:#ff962e}.option-scroll img{width:100%;height:100%;object-fit:cover}.option-scroll.dragging{cursor:grabbing}.option-note{padding:12px 14px;background:#f7f7f8;border-radius:6px;margin-top:17px}.option-note summary{font-size:12px;cursor:pointer}.option-note p{font-size:12px;line-height:1.7;color:#777}.original-name{font-size:12px;color:#888;margin-bottom:18px}.original-name summary{cursor:pointer}.qc-section{max-width:1120px;margin:0 auto 40px;border-top:1px solid #ececf0;padding-top:20px}.search-page{max-width:1100px;margin:40px auto}.search-page h1{font-size:42px;letter-spacing:-1.5px}.upload-box{border:2px dashed #dfdfe6;border-radius:12px;padding:32px;display:flex;gap:24px;align-items:center;background:#fafafa;margin:25px 0}.upload-box label{cursor:pointer}.upload-box input{max-width:100%;margin-top:12px}.upload-box img{width:110px;height:110px;object-fit:contain;border-radius:8px;background:#eee}.coverage{display:flex;flex-wrap:wrap;gap:10px 24px;padding:15px 0;border-bottom:1px solid #eee;font-size:12px;color:#777;line-height:1.8}.result-info{font-size:11px;color:#777;margin:7px 0}.fx-status{min-height:18px}.copy-fallback{width:100%;padding:10px;border:1px solid #ddd;font-size:12px}.foot .brand img{width:110px}@media(max-width:1050px){.nav{gap:12px;padding:17px 24px}.nav nav{gap:13px;margin:0}.nav .tools{gap:5px}.join{display:none}.brand img{width:100px}}@media(max-width:650px){.nav{padding:13px 18px}.nav nav{gap:10px;overflow-x:auto;justify-content:flex-start;padding-bottom:3px;scrollbar-width:none}.nav .tools select{padding:7px 4px;font-size:11px;max-width:98px}.subbrand{display:none}.detail{grid-template-columns:1fr;gap:14px}.detail h1{font-size:26px}.option-scroll{grid-template-columns:repeat(6,minmax(0,1fr));max-height:175px}.gallery-panel{margin-top:18px}.detail .thumbs{display:none}.search-page{margin:25px auto}.search-page h1{font-size:32px}.upload-box{padding:18px;display:block}.upload-box img{margin:12px 0}.heroart{height:220px}.camera{padding:0 9px}.search button{padding:0 14px}.qc-section h2{font-size:20px}.agent-grid{grid-template-columns:repeat(3,1fr)}}`;
function imageSearchPage(l){return `<section class="search-page"><div class="eyebrow">ORIENTDIG GRID</div><h1>${ui(l,'imageSearch')}</h1><p class="lead">${ui(l,'uploadHelp')}</p><div class="upload-box" id="drop-zone"><img id="query-image" hidden alt="${ui(l,'imageSearch')}"><div><button type="button" class="btn upload-trigger" id="choose-image">${camera} ${ui(l,'upload')}</button><input id="image-file" type="file" hidden accept="image/jpeg,image/png,image/webp"><p id="file-name" class="small" aria-live="polite"></p><p class="small">JPG · PNG · WebP / 15 MB</p></div></div><div class="coverage" id="coverage" aria-live="polite"></div><p id="image-status" class="small" role="status"></p><h2 id="results-heading" hidden>${ui(l,'matches')}</h2><div class="grid" id="image-results"></div><p class="small">${ui(l,'searchDisclaimer')}</p></section>`}
function agentPanel(p,l){return `<details class="agents"><summary>${ui(l,'agents')}</summary><div class="agent-grid">${p.agents.filter(a=>!/^Orientdig$/i.test(a.name)).map(a=>`<a href="${esc(a.url)}" target="_blank" rel="nofollow noopener">${esc(a.name)} →</a>`).join('')}</div></details>`}
function stylesPanel(p,l){const styles=p.styles||[];return `<section class="styles-panel" aria-labelledby="styles-title"><div class="gallery-heading"><h2 id="styles-title">${ui(l,'styles')}</h2><span class="small">${styles.length||''}</span></div>${styles.length?`<div class="option-scroll" tabindex="0" aria-label="${ui(l,'styles')}">${styles.map(v=>`<button type="button" data-style-image="${esc(v.image)}" data-style-name="${esc(styleName(v.name,l))}" aria-pressed="false" aria-label="${esc(styleName(v.name,l))}" title="${esc(styleName(v.name,l))}"><img src="${esc(v.image)}" alt="${esc(styleName(v.name,l))}" loading="lazy" draggable="false"></button>`).join('')}</div><p id="selected-style" class="small" aria-live="polite"></p>`:`<p class="small">${p.styleStatus==='unavailable'?messages[l][34]:STYLE_EMPTY[l]}</p>`}</section>`}
function galleryPanel(p,l){const photos=p.images;return `<section class="qc-section detail-photo-section" aria-labelledby="detail-photos-title"><div class="gallery-heading"><h2 id="detail-photos-title">${messages[l][38]} / ${ui(l,'qc')}</h2><span class="small">${photos.length}</span></div>${photos.length?`<div class="detail-photo-grid" aria-label="${ui(l,'selectPhoto')}">${photos.map((src,i)=>`<button data-image="${esc(src)}" data-photo-index="${i}" aria-pressed="${i===0}" aria-label="${messages[l][23]} ${i+1}"><img src="${esc(src)}" alt="${esc(name(p.name,l,p.path))} — ${i+1}" loading="lazy"></button>`).join('')}</div><p class="small">${messages[l][39]}</p>`:`<p class="small">${ui(l,'noQc')}</p>`}</section>`}
async function apiRoute(request,u){let path=u.pathname;if(path==='/api/image-index'){const l=locales[u.searchParams.get('lang')]?u.searchParams.get('lang'):'en';return Response.json({...SEARCH_INDEX,items:SEARCH_INDEX.items.map(p=>[p[0],p[1],p[2],{[l]:localizedTitle(p[1],l,p[0])}])},{headers:{'cache-control':'public,max-age=300'}});}if(path==='/logo.png'||path==='/favicon.png'){return fetch(ORIGIN+'/template/moban/pc/static/images/orientdig.webp',{cf:{cacheTtl:86400,cacheEverything:true}})}if(path==='/app-v2.js')return new Response(CLIENT+'\n'+STYLE_CLIENT,{headers:{'content-type':'text/javascript;charset=utf-8','cache-control':'public,max-age=60'}});if(path==='/api/rates'){try{let r=await fetch('https://api.frankfurter.dev/v2/rates?base=USD&quotes=EUR,GBP,CNY,JPY,KRW,CAD,AUD,CHF,PLN,BRL',{signal:AbortSignal.timeout(10000),cf:{cacheTtl:3600,cacheEverything:true}});if(!r.ok)throw Error();let rows=await r.json();if(!Array.isArray(rows)||!rows.length)throw Error();return Response.json({base:'USD',rates:Object.fromEntries([['USD',1],...rows.map(x=>[x.quote.toUpperCase(),x.rate])]),date:rows.map(x=>x.date).sort().at(-1),provider:'Frankfurter'},{headers:{'cache-control':'public,max-age=3600'}})}catch{return Response.json({error:'rates_unavailable'},{status:503})}}return null}

