function pagination(l,p,pages,total,filters){
 const [pageLabel,jumpLabel,go,first,last]=PAGE_LABELS[l],t=messages[l];
 const link=n=>'?'+new URLSearchParams({...filters,page:String(n)});
 const nav=(n,label,enabled)=>enabled?`<a href="${esc(link(n))}">${label}</a>`:`<span class="page-disabled" aria-disabled="true">${label}</span>`;
 return `<nav class="pager pager-full" aria-label="${pageLabel}"><div class="page-navigation">${nav(1,'« '+first,p>1)}${nav(p-1,'← '+t[25],p>1)}<span class="page-count" aria-live="polite">${pageLabel} <strong>${p}</strong> / <strong>${pages}</strong></span>${nav(p+1,t[26]+' →',p<pages)}${nav(pages,last+' »',p<pages)}</div><div class="page-tools"><span class="small">${new Intl.NumberFormat(l).format(total)} ${PAGE_PRODUCTS[l]}</span><form class="page-jump" method="get">${Object.entries(filters).filter(([,v])=>v).map(([k,v])=>`<input type="hidden" name="${k}" value="${esc(v)}">`).join('')}<label for="page-number">${jumpLabel}</label><input id="page-number" name="page" type="number" inputmode="numeric" min="1" max="${pages}" step="1" value="${p}" required><button type="submit">${go}</button></form></div></nav>`;
}
const paginationCSS=`.pager-full{display:flex;flex-direction:column;align-items:center;gap:16px;padding:28px 0}.page-navigation,.page-tools,.page-jump{display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap}.page-navigation a,.page-disabled{padding:11px 14px;border:1px solid #deded8;border-radius:6px;font-size:13px}.page-navigation a:hover{border-color:#ff9427;background:#fff4e7}.page-disabled{opacity:.4}.page-count{font-size:14px;white-space:nowrap;padding:0 10px}.page-jump{gap:8px;font-size:13px}.page-jump input[type=number]{width:78px;padding:9px;border:1px solid #d7d7d0;border-radius:5px;background:white}.page-jump button{padding:10px 16px;border:0;border-radius:5px;background:#ff9427;color:#171717}.page-tools{gap:24px}@media(max-width:650px){.pager-full{gap:12px;padding:20px 0}.page-navigation{gap:6px}.page-navigation a,.page-disabled{padding:8px 7px;font-size:11px}.page-count{font-size:12px;padding:0 3px}.page-tools{gap:10px}.page-jump{font-size:12px;gap:6px}}`;

