const styleOverviewCSS=`.style-overview-scroll{display:grid;grid-template-columns:repeat(auto-fill,minmax(70px,1fr));gap:8px;max-height:224px;overflow-y:auto;scrollbar-gutter:stable;padding:2px 8px 2px 2px;overscroll-behavior:contain}.style-overview-photo{padding:0;border:2px solid transparent;border-radius:8px;aspect-ratio:1;background:#f3f2ef;overflow:hidden;cursor:pointer}.style-overview-photo[aria-pressed=true]{border-color:#ff9427}.style-overview-photo img{width:100%;height:100%;display:block;object-fit:contain}.styles-panel .small{margin-top:12px}.style-overview-photo:focus-visible{outline:2px solid #222}@media(max-width:650px){.style-overview-scroll{max-height:174px;grid-template-columns:repeat(auto-fill,minmax(60px,1fr))}}`;

const STYLE_CLIENT=`(()=>{const styles=[...document.querySelectorAll('[data-style-image]')],main=document.getElementById('mainphoto'),counter=document.getElementById('photo-counter'),label=document.getElementById('selected-style');if(!main||!styles.length)return;const clear=()=>{styles.forEach(b=>b.setAttribute('aria-pressed','false'));label.textContent=''};styles.forEach((b,i)=>b.addEventListener('click',()=>{main.src=b.dataset.styleImage;main.alt=b.dataset.styleName;label.textContent=b.dataset.styleName;counter.textContent=(i+1)+' / '+styles.length;styles.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-image]').forEach(x=>x.setAttribute('aria-pressed','false'))}));document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',clear));})();`;

const STYLE_COLORS={en:'Black|White|Green',de:'Schwarz|Weiß|Grün',fr:'Noir|Blanc|Vert',es:'Negro|Blanco|Verde',it:'Nero|Bianco|Verde',nl:'Zwart|Wit|Groen',pt:'Preto|Branco|Verde',pl:'Czarny|Biały|Zielony',ro:'Negru|Alb|Verde',sv:'Svart|Vit|Grön',zh:'黑色|白色|绿色',da:'Sort|Hvid|Grøn',fi:'Musta|Valkoinen|Vihreä',el:'Μαύρο|Λευκό|Πράσινο',cs:'Černá|Bílá|Zelená',hu:'Fekete|Fehér|Zöld',bg:'Черно|Бяло|Зелено',sk:'Čierna|Biela|Zelená',hr:'Crna|Bijela|Zelena',ja:'ブラック|ホワイト|グリーン',ko:'검정|흰색|초록',vi:'Đen|Trắng|Xanh lá',th:'ดำ|ขาว|เขียว',id:'Hitam|Putih|Hijau'};
function styleName(value,l){const colors=(STYLE_COLORS[l]||STYLE_COLORS.en).split('|');return value.replace(/黑色|白色|绿色|Black|White|Green/gi,m=>colors[({'黑色':0,'白色':1,'绿色':2,black:0,white:1,green:2})[m.toLowerCase()]]);}
